draw(A--F,dashed);
draw(B--F,dashed);
draw(C--F,dashed);
draw(A--(a,-1),dashed);
draw(B--(b,-1),dashed);
draw(C--(c,-1),dashed);
draw((-3,-2)--(-3,5.5));

